import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Send, Phone, Video, User, Clock } from 'lucide-react';

const ChatWindow = ({ 
  conversation, 
  messages = [], 
  loading, 
  onSendMessage, 
  onClose,
  isAdmin = false 
}) => {
  const [inputMessage, setInputMessage] = useState('');
  const [isSending, setIsSending] = useState(false);
  const messagesEndRef = useRef(null);

  // Récupérer userData
  const userData = useMemo(() => {
    try {
      const storedData = localStorage.getItem('userData');
      return storedData ? JSON.parse(storedData) : {};
    } catch (error) {
      console.error('Erreur lors du parsing de userData:', error);
      return {};
    }
  }, []);

  // Déterminer le nom de l'autre personne
  const otherUserName = useMemo(() => {
    if (!conversation) return '';

    if (isAdmin) {
      // Pour les admins, montrer le nom de l'utilisateur
      return `${conversation.first_name || ''} ${conversation.last_name || ''}`.trim();
    } else {
      // Pour les utilisateurs, montrer le nom de l'admin
      return `${conversation.admin_first_name || ''} ${conversation.admin_last_name || ''}`.trim();
    }
  }, [conversation, isAdmin]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    const trimmedMessage = inputMessage.trim();
    if (!trimmedMessage || !conversation) return;

    setIsSending(true);
    try {
      await onSendMessage(conversation.id, trimmedMessage);
      setInputMessage('');
    } catch (error) {
      console.error('Erreur:', error);
    } finally {
      setIsSending(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  // Vérifier si on a un vrai contenu à afficher
  const hasContent = conversation && messages;

  if (!hasContent) {
    return (
      <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-2xl border border-white/40 dark:border-neutral-800/60 h-[600px] flex flex-col items-center justify-center">
        <div className="text-center p-8">
          <div className="h-20 w-20 rounded-2xl bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center mx-auto mb-6">
            <User className="h-10 w-10 text-white" />
          </div>
          <h3 className="text-xl font-bold text-neutral-900 dark:text-white mb-3">
            {isAdmin ? 'Sélectionnez un client' : 'Sélectionnez une conversation'}
          </h3>
          <p className="text-neutral-600 dark:text-neutral-400">
            {isAdmin 
              ? 'Choisissez une conversation pour aider un utilisateur' 
              : 'Sélectionnez une conversation pour discuter avec notre équipe'
            }
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-2xl border border-white/40 dark:border-neutral-800/60 h-[600px] flex flex-col overflow-hidden">
      {/* Header */}
      <div className="flex-shrink-0 p-4 sm:p-6 border-b border-neutral-200/50 dark:border-neutral-800/50 flex items-center justify-between">
        <div className="flex items-center gap-3 flex-1">
          <div className="h-10 w-10 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center text-white font-bold">
            {otherUserName?.charAt(0).toUpperCase() || '?'}
          </div>
          <div className="flex-1 min-w-0">
            <h3 className="font-semibold text-neutral-900 dark:text-white truncate">
              {otherUserName || 'Utilisateur'}
            </h3>
            <div className="flex items-center gap-2 text-xs text-neutral-500">
              <div className="flex items-center gap-1">
                <div className="h-2 w-2 bg-green-500 rounded-full"></div>
                <span>En ligne</span>
              </div>
              {isAdmin && (
                <>
                  <span>•</span>
                  <span>{conversation.email}</span>
                </>
              )}
            </div>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors">
            <Phone className="w-5 h-5 text-neutral-600 dark:text-neutral-400" />
          </button>
          <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors">
            <Video className="w-5 h-5 text-neutral-600 dark:text-neutral-400" />
          </button>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-4">
        {loading ? (
          <div className="flex justify-center items-center h-full">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-500"></div>
          </div>
        ) : messages.length === 0 ? (
          <div className="flex flex-col justify-center items-center h-full text-center">
            <div className="h-16 w-16 rounded-full bg-gradient-to-r from-primary-500/10 to-secondary-500/10 flex items-center justify-center mb-4">
              <User className="h-8 w-8 text-primary-500" />
            </div>
            <h4 className="font-medium text-neutral-900 dark:text-white mb-2">
              Commencez la conversation
            </h4>
            <p className="text-sm text-neutral-500 max-w-xs">
              {isAdmin 
                ? 'Envoyez le premier message pour aider cet utilisateur' 
                : 'Envoyez votre premier message à notre équipe de support'
              }
            </p>
          </div>
        ) : (
          messages.map((message, index) => {
            const isOwn = message.sender_id === userData.id;
            const showSenderName = !isOwn && isAdmin;

            return (
              <div key={message.id || index} className={`flex ${isOwn ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-xs lg:max-w-md ${isOwn ? 'ml-auto' : ''}`}>
                  {showSenderName && (
                    <div className="flex items-center gap-2 mb-1 ml-1">
                      <div className="h-6 w-6 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center text-white text-xs">
                        {otherUserName?.charAt(0).toUpperCase() || '?'}
                      </div>
                      <span className="text-xs font-medium text-neutral-700 dark:text-neutral-300">
                        {otherUserName}
                      </span>
                    </div>
                  )}
                  <div
                    className={`px-4 py-2 rounded-2xl ${
                      isOwn
                        ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-br-none'
                        : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-900 dark:text-white rounded-bl-none'
                    }`}
                  >
                    <p className="text-sm break-words">{message.content}</p>
                    <div className="flex items-center justify-between mt-1">
                      <p className={`text-xs ${isOwn ? 'text-white/70' : 'text-neutral-500'}`}>
                        <Clock className="inline w-3 h-3 mr-1" />
                        {new Date(message.created_at).toLocaleTimeString('fr-FR', {
                          hour: '2-digit',
                          minute: '2-digit'
                        })}
                      </p>
                      {isOwn && (
                        <div className={`text-xs ${message.is_read ? 'text-blue-300' : 'text-white/50'}`}>
                          {message.is_read ? '✓✓' : '✓'}
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            );
          })
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <div className="flex-shrink-0 p-4 sm:p-6 border-t border-neutral-200/50 dark:border-neutral-800/50">
        <div className="flex items-end gap-3">
          <textarea
            value={inputMessage}
            onChange={(e) => setInputMessage(e.target.value)}
            onKeyPress={handleKeyPress}
            placeholder={isAdmin ? "Écrivez votre réponse..." : "Écrivez votre message..."}
            rows="1"
            className="flex-1 px-4 py-3 bg-neutral-100 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-2xl text-sm text-neutral-900 dark:text-white placeholder-neutral-500 focus:outline-none focus:ring-2 focus:ring-primary-500 resize-none"
          />
          <button
            onClick={handleSend}
            disabled={isSending || !inputMessage.trim()}
            className="flex-shrink-0 p-3 bg-gradient-to-r from-primary-500 to-secondary-500 hover:from-primary-600 hover:to-secondary-600 disabled:opacity-50 text-white rounded-lg transition-all"
          >
            {isSending ? (
              <div className="animate-spin h-5 w-5 border-2 border-white border-t-transparent rounded-full"></div>
            ) : (
              <Send className="w-5 h-5" />
            )}
          </button>
        </div>
        {isAdmin && (
          <p className="text-xs text-neutral-500 mt-2 text-center">
            Réponse moyenne attendue : 5-10 minutes
          </p>
        )}
      </div>
    </div>
  );
};

export default ChatWindow;
